"use client";
import {
  useId,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import "./folder-fan.css";
import { useControllableState } from "./use-controllable-state";
export interface FolderItem {
  id: string;
  label: string;
  content?: ReactNode;
  color?: string;
}
export interface FolderFanProps {
  className?: string;
  style?: CSSProperties;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  items: FolderItem[];
  title?: string;
  onSelect?: (id: string) => void;
  spread?: number;
  direction?: "up" | "right";
  material?: "paper" | "glass";
  color?: string;
  duration?: number;
  trigger?: "press" | "hover";
}
/** One card tree through pocket and fan. CSS retargets from the current presentation.
 * Hover is optional; the toggle remains operable by touch and keyboard.
 */
export function FolderFan({
  items,
  className = "",
  style,
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  title = "Collection",
  onSelect,
  spread = 12,
  direction = "up",
  material = "glass",
  color = "#a8c6ee",
  duration = 560,
  trigger = "press",
}: FolderFanProps) {
  const [pinned, setPinned] = useControllableState(
    controlled,
    defaultOpen,
    onOpenChange,
  );
  const [hovered, setHovered] = useState(false);
  const root = useRef<HTMLDivElement>(null),
    id = useId();
  const open = pinned || (trigger === "hover" && hovered);
  const side = direction === "right";
  return (
    <div
      ref={root}
      data-direction={direction}
      data-material={material}
      className={`roc-folder ${open ? "is-open" : ""} ${className}`}
      style={
        {
          "--folder-color": color,
          "--roc-duration": `${duration}ms`,
          ...style,
        } as CSSProperties
      }
      onPointerEnter={(e) => {
        if (e.pointerType === "mouse") setHovered(true);
      }}
      onPointerLeave={() => setHovered(false)}
      onKeyDown={(e) => {
        if (e.key === "Escape" && open) {
          e.stopPropagation();
          setPinned(false);
          setHovered(false);
          root.current
            ?.querySelector<HTMLButtonElement>(".roc-folder-toggle")
            ?.focus();
        }
      }}
    >
      <div className="roc-folder-back" aria-hidden="true" />
      <div
        id={id}
        className="roc-folder-items"
        inert={!open}
        aria-hidden={!open}
      >
        {items.map((item, index) => {
          const n = index - (items.length - 1) / 2;
          const unit = items.length < 2 ? 0 : n / ((items.length - 1) / 2);
          return (
            <button
              type="button"
              key={item.id}
              data-roc-item
              className="roc-folder-card"
              onClick={() => onSelect?.(item.id)}
              style={{
                background: item.color,
                left: side
                  ? open
                    ? `${66 + Math.abs(unit) * 3}%`
                    : "28%"
                  : open
                    ? `${50 + unit * (13 + spread * 0.45)}%`
                    : "50%",
                top: side
                  ? open
                    ? `${50 + unit * (12 + spread * 0.3)}%`
                    : "57%"
                  : open
                    ? `${28 + Math.abs(unit) * 2}%`
                    : "56%",
                transform: `translate(-50%, -50%) rotate(${open ? unit * spread : n * 4}deg) scale(${open ? 1 : 0.87})`,
                zIndex: index + 1,
              }}
            >
              <span className="roc-eyebrow">
                {String(index + 1).padStart(2, "0")}
              </span>
              <strong>{item.label}</strong>
              <span className="roc-card-content">{item.content}</span>
            </button>
          );
        })}
      </div>
      <button
        type="button"
        className="roc-folder-toggle"
        aria-expanded={open}
        aria-controls={id}
        onClick={() => {
          setPinned(!open);
          setHovered(false);
        }}
      >
        <span>{title}</span>
        <span>
          {items.length} objects <b>{open ? "−" : "+"}</b>
        </span>
      </button>
    </div>
  );
}

@import "./surface.css";
.roc-folder {
  height: 340px;
  width: 100%;
  max-width: 500px;
  position: relative;
  isolation: isolate;
  margin: auto;
  container-type: inline-size;
}
.roc-folder-back {
  position: absolute;
  left: 50%;
  top: 49%;
  width: 210px;
  height: 150px;
  transform: translateX(-50%);
  border-radius: 8px 18px 15px 15px;
  background: color-mix(in srgb, var(--folder-color, #a8c6ee), #454d5c 13%);
  border: 1px solid #ffffff50;
  box-shadow: inset 0 1px #ffffff70;
  transition: left var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1);
}
.roc-folder-back:before {
  content: "";
  position: absolute;
  width: 80px;
  top: -14px;
  height: 25px;
  background: inherit;
  border-radius: 9px 14px 0 0;
}
.roc-folder-items {
  position: absolute;
  inset: 0;
  z-index: 1;
}
.roc-folder-card {
  position: absolute;
  width: 118px;
  height: 152px;
  padding: 12px;
  text-align: left;
  border: 1px solid #ffffff70;
  border-radius: var(--roc-radius, 9px);
  background: var(--roc-paper, #fffcf6);
  box-shadow: 0 5px 14px #22222216;
  transform-origin: center;
  transition:
    left var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    top var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    transform var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    box-shadow 0.2s;
}
.roc-folder-card:hover {
  box-shadow: 0 13px 24px #22222220;
}
.roc-folder-card strong {
  display: block;
  font:
    normal 20px/1.15 Georgia,
    serif;
  margin-top: 18px;
  overflow-wrap: anywhere;
}
.roc-card-content {
  display: block;
  margin-top: 12px;
  font-size: 10px;
  line-height: 1.5;
  color: var(--roc-muted, #757b72);
}
.roc-folder-toggle {
  position: absolute;
  z-index: 2;
  left: 50%;
  top: 58%;
  width: 228px;
  height: 133px;
  padding: 22px;
  border: 1px solid #ffffff90;
  border-radius: 9px 9px 19px 19px;
  text-align: left;
  transform: translateX(-50%);
  transform-origin: 50% 100%;
  background: var(--folder-color, #a8c6ee);
  box-shadow:
    inset 0 1px 1px #ffffff70,
    0 14px 24px #2933420c;
  transition:
    transform var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    left var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    background 0.25s;
}
.roc-folder-toggle > span:first-child {
  display: block;
  font-size: 13px;
  margin-bottom: 25px;
}
.roc-folder-toggle > span:last-child {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #273344a6;
}
.roc-folder-toggle b {
  font-size: 18px;
  font-weight: 400;
}
.roc-folder[data-material="glass"] .roc-folder-toggle {
  background: color-mix(in srgb, var(--folder-color, #a8c6ee) 67%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.roc-folder.is-open .roc-folder-toggle {
  transform: translateX(-50%) perspective(650px) rotateX(-24deg);
}
.roc-folder[data-direction="right"] .roc-folder-back,
.roc-folder[data-direction="right"] .roc-folder-toggle {
  left: 28%;
  width: 162px;
}
.roc-folder[data-direction="right"] .roc-folder-toggle {
  transform-origin: 0% 50%;
}
.roc-folder[data-direction="right"].is-open .roc-folder-toggle {
  transform: translateX(-50%) perspective(650px) rotateY(-26deg);
}
@container (max-width:350px) {
  .roc-folder-card {
    width: 94px;
    height: 143px;
  }
  .roc-folder-card strong {
    font-size: 17px;
  }
  .roc-folder-toggle {
    width: 200px;
  }
  .roc-folder-back {
    width: 190px;
  }
  .roc-folder[data-direction="right"] .roc-folder-toggle,
  .roc-folder[data-direction="right"] .roc-folder-back {
    width: 132px;
  }
  .roc-folder[data-direction="right"] .roc-folder-toggle {
    padding: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-folder * {
    transition: none !important;
  }
}

/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: 2px solid var(--roc-accent, #64735f);
  outline-offset: 3px;
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}
